        assert_eq!(Opcode::Push as u8, 0x01);
        assert_eq!(Opcode::PushS as u8, 0x02);
        assert_eq!(Opcode::Dup as u8, 0x03);
        assert_eq!(Opcode::Drop as u8, 0x04);
        assert_eq!(Opcode::Swap as u8, 0x05);
