        assert_eq!(Opcode::Sub as u8, 0x11);
        assert_eq!(Opcode::Mul as u8, 0x12);
        assert_eq!(Opcode::Div as u8, 0x13);
        assert_eq!(Opcode::Mod as u8, 0x14);
